public boolean isCoveringBackline() {
    return kind == Kind.SHIELD && isAlive() && skillId() == 0 && !navigation.isDone()
            && level().getGameTime() < coverUntil && validEnemy(getTarget());
}
public AttackState skillPhase() { return AttackState.values()[Math.min(AttackState.values().length - 1, Math.max(0, entityData.get(PHASE)))]; }
public float actionAge(float partialTick) { return skillStartTime() < 0 ? 0 : Math.max(0, level().getGameTime() - skillStartTime() + partialTick) * skillSpeed(); }

@Override protected void defineSynchedData() {

/** The same validation gates AI and operator/GameTest starts; no client can request a damage frame. */
public boolean startSkill(int id, LivingEntity target) {
    if (level().isClientSide || !isAlive() || isRemoved() || !allows(id)) return false;
    SkillDefinition base = TemplateSkills.byId(id);
    if (base == null || (id == ArmySkills.SCORPION_EMERGE && target == this ? false : id == TemplateSkills.POSSESSION ? !validSupport(target) : !validEnemy(target))) return false;
    double range = distanceTo(target);
    if (range < base.minRange() || range > (id == ArmySkills.AXE_COUNTER ? 40 : base.maxRange()) || id != ArmySkills.SCORPION_EMERGE && base.requiresSight() && !hasLineOfSight(target)) return false;
    if (id == TemplateSkills.ROCK_THROW && !onHighGround(target)) return false;
    if (army != null && !army.canStart(id,target)) return false;
    Vec3 direction = target.position().subtract(position()).multiply(1, 0, 1).normalize();
    if (direction.lengthSqr() < .0001) direction = getLookAngle().multiply(1, 0, 1).normalize();
    // A fuse uses real elapsed time, not attack speed: three consecutive close seconds.
    float speed = id != ArmySkills.DETONATE && id != ArmySkills.AXE_COUNTER && id != ArmySkills.CHILD_CURSE && id != ArmySkills.SKULL_DIVE && id != ArmySkills.SKULL_BLOOD && id != ArmySkills.TOAD_LEAP && id != ArmySkills.SERPENT_COIL && id != ArmySkills.SERPENT_BITE && id != ArmySkills.STONE_SLAM && id != ArmySkills.STONE_UPPERCUT && id != ArmySkills.DOG_BITE && id != ArmySkills.DOG_ALARM && kind != Kind.BRONZE_SNAKE && kind != Kind.MINING_SPIDER && kind != Kind.LANTERN_BAT && kind != Kind.BLIND_FISH && kind != Kind.DROWNER && kind != Kind.BIXI && kind != Kind.CENTIPEDE && kind != Kind.YECHA && kind != Kind.PALANQUIN && hasEffect(BlueprintEntities.BINGSHA_POSSESSION.get()) ? 1.3F : 1F;
    SkillDefinition effective = TemplateSkills.accelerated(base, speed);
    if (!attack.tryStart(effective, level().getGameTime(), position(), direction, target.getUUID())) return false;
    if(army!=null)army.started(id,target);
    entityData.set(SPEED, speed);
    coverUntil = 0;
    entityData.set(SKILL, id); entityData.set(START, attack.started()); entityData.set(PHASE, AttackState.WINDUP.ordinal());
    navigation.stop(); face(direction);
    if (id == TemplateSkills.POSSESSION) entityData.set(BUFF_TARGET, target.getId());
    if (id == TemplateSkills.POUNCE) {
        Vec3 towards = target.position().subtract(position()).multiply(1, 0, 1);
        leapDestination = position().add(towards.normalize().scale(Math.min(5.6, towards.length())));
    }
    BlueprintVisualEvent.start(this, effective, attack.origin(), attack.direction(), target.getId());

if (now >= nextTacticalScan) { nextTacticalScan = now + 20; updateTactics(now); }
if (possessedUntil > 0) {
    LivingEntity source = resolve(possessor);
    // An unloaded ally could not receive releaseSupport when its priest died or
    // changed links. Reconcile once both are loaded; a missing UUID alone is not death.
    if (now >= possessedUntil || source != null && (!source.isAlive()
            || source instanceof TemplateMob priest && (!getUUID().equals(priest.possessedAlly)
                    || !priest.validSupport(this))))
        clearPossession();
}
entityData.set(POSSESSED, hasEffect(BlueprintEntities.BINGSHA_POSSESSION.get()));
LivingEntity linked = resolve(possessedAlly);
if (linkUntil > 0 && (now >= linkUntil || linked != null && !validSupport(linked))) releaseSupport();
if (linked != null && linkUntil > now) entityData.set(BUFF_TARGET, linked.getId());
if (attack.current() != null) {
    face(attack.direction());
    navigation.stop();
    if (skillId() != TemplateSkills.POUNCE && skillId() != ArmySkills.ROLL && skillId() != ArmySkills.GRAPPLE && skillId() != ArmySkills.SKULL_DIVE && skillId() != ArmySkills.BAT_DIVE && skillId() != ArmySkills.YECHA_GRAB && skillId() != ArmySkills.TOAD_LEAP)
        setDeltaMovement(getDeltaMovement().multiply(.35, 1, .35));
    attack.advance(now, this::impact);
    // Damage callbacks (e.g. thorns) may synchronously enter die(). Do not erase its
    // authoritative death clock or cancel the death visual that die() has just sent.
    if (!isAlive()) return;
    if (attack.current() == null && skillId() != 0) finishAction();
}
entityData.set(PHASE, attack.state(now).ordinal());
if(kind==Kind.BRONZE_SNAKE){
    boolean bars=false;
    if(horizontalCollision)for(var d:Direction.Plane.HORIZONTAL)for(int y=0;y<2;y++){
        var p=blockPosition().relative(d).above(y);
        if(level().hasChunkAt(p)&&level().getBlockState(p).is(net.minecraft.world.level.block.Blocks.IRON_BARS))bars=true;
    }
    entityData.set(CLIMBING,bars&&isAlive());

    attack.cancel(); finishAction(); entityData.set(PHASE, attack.state(level().getGameTime()).ordinal());
}
private void finishAction() {
    entityData.set(SKILL, 0); entityData.set(START, -1L); entityData.set(SPEED, 1F);
    syncHook(null,-1);
    if (linkUntil == 0) entityData.set(BUFF_TARGET, -1);
    BlueprintVisualEvent.cancel(this);
}
private void face(Vec3 direction) {
    if(kind==Kind.BRONZE_SNAKE&&(skillId()==ArmySkills.BRONZE_REAR_STAB||skillId()==ArmySkills.BRONZE_POISON))direction=direction.scale(-1);
    float yaw = (float)(Math.atan2(direction.z, direction.x) * 180 / Math.PI) - 90;
    setYRot(yaw); yBodyRot = yaw; yHeadRot = yaw;
}

}
@Override public boolean onClimbable() {
    if(kind==Kind.CENTIPEDE)return isAlive()&&(horizontalCollision||hanging());
    // A dead wall-climber must fall under ordinary gravity. Keeping the last synchronized
    // climbing flag would continue vanilla's wall boost / slow-fall during its death clip.
    if (kind == Kind.BEAST || kind == Kind.BRONZE_SNAKE) return isAlive() && (entityData.get(CLIMBING) || super.onClimbable());
    return super.onClimbable();
}
@Override public boolean canBreatheUnderwater(){return kind==Kind.TOAD||kind==Kind.SERPENT||kind==Kind.DROWNER||super.canBreatheUnderwater();}
@Override public boolean checkSpawnObstruction(net.minecraft.world.level.LevelReader reader){
    return (kind==Kind.TOAD||kind==Kind.SERPENT||kind==Kind.DROWNER)?reader.isUnobstructed(this):super.checkSpawnObstruction(reader);
}
@Override public void travel(Vec3 input) {
    if(kind==Kind.TREE&&!treeAwake()&&isAlive()){
        setDeltaMovement(0,getDeltaMovement().y,0);super.travel(Vec3.ZERO);return;
    }
    if((kind==Kind.TOAD||kind==Kind.SERPENT||kind==Kind.DROWNER)&&isAlive()&&isInWater()&&isControlledByLocalInstance()){
        moveRelative(.1F,input);move(net.minecraft.world.entity.MoverType.SELF,getDeltaMovement());
        setDeltaMovement(getDeltaMovement().scale(.8));calculateEntityAnimation(false);return;
    }
    if ((kind != Kind.SKULL && kind != Kind.LANTERN_BAT && kind != Kind.BLIND_FISH && kind != Kind.YECHA) || !isAlive() || isInWater() || isInLava()) {
        super.travel(input); return;
    }
    // FlyingMoveControl supplies vertical input; ground travel uses ground friction
    // and cannot provide a controlled ascent after the bite. Keep normal collision.
    if (isControlledByLocalInstance()) {
        moveRelative(.1F, input);
        move(net.minecraft.world.entity.MoverType.SELF, getDeltaMovement());
        setDeltaMovement(getDeltaMovement().scale(.85));
    }
    calculateEntityAnimation(true);
}

@Override public boolean causeFallDamage(float distance, float multiplier, DamageSource source) {
    return kind == Kind.BEAST || kind == Kind.TOAD ? super.causeFallDamage(Math.max(0, distance - 5), multiplier, source) : super.causeFallDamage(distance, multiplier, source);

@Override public void die(DamageSource source) {
    if (deathStarted >= 0) return;
    super.die(source);
    if (!isDeadOrDying()) return;
    if(kind==Kind.SKULL||kind==Kind.LANTERN_BAT||kind==Kind.BLIND_FISH||kind==Kind.YECHA)setNoGravity(false);
    deathStarted = level().getGameTime(); attack.cancel(); navigation.stop(); setTarget(null); releaseSupport(); clearPossession();
    syncHook(null,-1);
    entityData.set(CLIMBING, false);
    if(kind==Kind.MINING_SPIDER||kind==Kind.CENTIPEDE)setNoGravity(false);
    clearClimbContact();
    entityData.set(SKILL, 0); entityData.set(START, deathStarted); entityData.set(SPEED, 1F);
    BlueprintVisualEvent.cancel(this);
    BlueprintVisualEvent.death(this);
    if(!level().isClientSide&&army!=null)army.died(source);
}
public int deathDuration() { return kind == Kind.PAPER ? 10 : kind == Kind.SHIELD ? 200 : kind == Kind.SWORD ? 60 : 44; }
void onArmyHookHit(LivingEntity target,long epoch) {
    if(!level().isClientSide&&army!=null&&isAlive()&&skillId()==ArmySkills.GRAPPLE&&skillStartTime()==epoch)
        army.hookHit(target);
}
@Override protected void dropAllDeathLoot(DamageSource source) {
    if (lootDropped) return;
    lootDropped = true; super.dropAllDeathLoot(source);
}
@Override protected void tickDeath() {
    ++deathTime;
    if(!level().isClientSide&&army!=null)army.tickDead(level().getGameTime());
    if (!level().isClientSide && deathStarted >= 0)
        deathTime = (int)Math.min(240, Math.max(deathTime, level().getGameTime() - deathStarted));
    if (kind == Kind.SHIELD) setDeltaMovement(Vec3.ZERO);
    else if(!level().isClientSide&&!isNoGravity()){
        // LivingEntity stops ordinary travel once dead. Gravity alone cannot drop a flying
        // corpse or a ceiling climber; keep the normal block/world-border collision path.
        var velocity=getDeltaMovement();
        if(onGround())setDeltaMovement(Vec3.ZERO);
        else{
            setDeltaMovement(velocity.x*.8,Math.max(-.8,velocity.y-.08),velocity.z*.8);
            move(net.minecraft.world.entity.MoverType.SELF,getDeltaMovement());
            if(onGround())setDeltaMovement(Vec3.ZERO);
        }
    }
    int duration = deathDuration();
    if (deathTime >= duration && !level().isClientSide && !isRemoved()) {
        level().broadcastEntityEvent(this, (byte)60); remove(RemovalReason.KILLED);
    }
}

public String visualAnimation() {
    if (isDeadOrDying()) return "death";
    if(kind==Kind.SCORPION&&burrowed())return "burrow";
    if(kind==Kind.TREE&&!treeAwake())return "camouflage";
    if (hurtTime > 0 && skillId() == 0) return "hurt";
    if(army!=null&&skillId()!=0)return army.animation(skillId());
    if (skillId() == TemplateSkills.POSSESSION) return "buff";
    if (skillId() == TemplateSkills.ROCK_THROW) return "rock";
    if (skillId() == TemplateSkills.POUNCE) return "skill";
    if (skillId() != 0) return "attack";
    if (kind == Kind.BEAST && onClimbable() && climbFace() != null) return "climb";
    if(kind==Kind.BRONZE_SNAKE&&onClimbable())return "climb";
    if (getDeltaMovement().horizontalDistanceSqr() > .001) return isSprinting() ? "run" : "walk";
    return "idle";
}
public AnimationProfile animationProfile(){return AnimationProfile.forKind(kind);}
@Override public AnimatableInstanceCache getAnimatableInstanceCache() { return animationCache; }
@Override public void registerControllers(AnimatableManager.ControllerRegistrar controllers) {
    controllers.add(new AnimationController<TemplateMob>(this, "body", 0, state -> {
        String animation = visualAnimation();
        state.getController().setAnimationSpeed(animationProfile().playbackRate(animation,getDeltaMovement().horizontalDistance(),getAttributeValue(Attributes.MOVEMENT_SPEED),isSprinting()));
        animationPartial = state.getPartialTick();
        if (lastAnimationStart != skillStartTime()) {
            lastAnimationStart = skillStartTime(); state.getController().forceAnimationReset();
        }
        RawAnimation sequence = RawAnimation.begin();
        String key = "animation." + blueprintId() + "." + animation;
        return state.setAndContinue(animationProfile().loops(animation)
                ? sequence.thenLoop(key) : sequence.thenPlayAndHold(key));
    }) {
        @Override protected double adjustTick(double tick) {
            boolean resetting = shouldResetTick;
            double local = super.adjustTick(tick);
            // GeckoLib polls a new queued clip only at transition tick zero. Replacing that
            // zero with a nonzero server age leaves the old idle clip installed forever.
            if (resetting || getAnimationState() != AnimationController.State.RUNNING) return local;
            if (kind == Kind.BEAST && climbFace() != null && climbStartTime() >= 0 && skillId() == 0 && isAlive())
                return Math.max(0, level().getGameTime() - climbStartTime() + animationPartial);
            // Late observers seek to the authoritative contact frame instead of restarting the clip.
            return skillStartTime() >= 0 && (skillId() != 0 || isDeadOrDying()) ? actionAge(animationPartial) : local;
        }
    });
}

package com.dynasty.blueprint.client;

import com.dynasty.blueprint.TemplateMob;
import net.minecraft.client.Minecraft;
import net.minecraft.core.Direction;
import net.minecraft.util.Mth;
import net.minecraft.world.phys.Vec3;
import net.minecraftforge.api.distmarker.Dist;
import net.minecraftforge.client.event.ClientPlayerNetworkEvent;
import net.minecraftforge.event.TickEvent;
import net.minecraftforge.eventbus.api.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;
import org.joml.Matrix4f;
import org.joml.Vector3f;
import org.joml.Quaternionf;
import software.bernie.geckolib.cache.object.GeoBone;
import java.util.LinkedHashMap;
import java.util.IdentityHashMap;
import java.util.Map;
import java.util.UUID;

/** Bounded cosmetic state. Dedicated identity bones isolate inertia/IK from authored actions. */
@Mod.EventBusSubscriber(modid="dynasty", value=Dist.CLIENT)
public final class TemplateSecondaryMotion {
    private static final String[] SIDES={"right", "left"};
    private static final String[] IK_PARTS={"shoulder", "elbow", "wrist", "thigh", "knee", "ankle"};
    private static final LinkedHashMap<UUID, Motion> STATES=new LinkedHashMap<>(64,.75F,true);
    private static Object world;
    private static final class Motion {
        long tick=Long.MIN_VALUE, seen;
        Vec3 velocity=Vec3.ZERO;
        float yaw, rightArm, leftArm;
        final float[] angle=new float[14], speed=new float[14], roll=new float[14], rollSpeed=new float[14];
        final float[] rail=new float[2], ik=new float[12], ikY=new float[12], ikZ=new float[12];
        final double[] plantedY=new double[4];
        final float[] scorpionFloor=new float[6],scorpionLeg=new float[12];
        final boolean[] stance=new boolean[4];
        Direction face;
    }
    private TemplateSecondaryMotion() {}
    @SubscribeEvent public static void logout(ClientPlayerNetworkEvent.LoggingOut event) { STATES.clear();world=null; }
    @SubscribeEvent public static void tick(TickEvent.ClientTickEvent event) {
        if(event.phase!=TickEvent.Phase.END)return;
        var level=Minecraft.getInstance().level;
        if(level!=world){STATES.clear();world=level;}
        if(level!=null&&level.getGameTime()%40==0)STATES.values().removeIf(s->level.getGameTime()-s.seen>80);
    }
    public static int activeStates(){return STATES.size();}
    public static void apply(TemplateMobModel model, TemplateMob mob, float partial) {
        // These bones have no authored animation. Reset on every draw, including far/dead entities,
        // because baked GeoBone objects may be reused when rendering another entity of this kind.
        resetProcedural(model,mob.kind());
        var mc=Minecraft.getInstance();
        if(mc.level!=world){STATES.clear();world=mc.level;}
        int distance=mob.animationProfile().secondaryDistance();
        if(!mob.isAlive()||mc.level==null||mc.gameRenderer.getMainCamera().getPosition().distanceToSqr(mob.position())>distance*distance){STATES.remove(mob.getUUID());return;}
        if(mob.kind()==TemplateMob.Kind.SWORD||mob.kind()==TemplateMob.Kind.POWDER)return;
        Motion s=STATES.computeIfAbsent(mob.getUUID(),id->new Motion());
        while(STATES.size()>64)STATES.remove(STATES.keySet().iterator().next());
        long now=mc.level.getGameTime();s.seen=now;
        boolean advance=!mc.isPaused()&&s.tick!=now;
        if(advance){
            boolean fresh=s.tick==Long.MIN_VALUE||now-s.tick>4;
            int steps=fresh?1:(int)Math.max(1,Math.min(4,now-s.tick));
            Vec3 v=mob.getDeltaMovement();float yaw=mob.yBodyRot;
            float armR=rotation(model,"right_shoulder"),armL=rotation(model,"left_shoulder");
            Vec3 accel=fresh?Vec3.ZERO:v.subtract(s.velocity);
            double rad=Math.toRadians(yaw);
            float forward=(float)(accel.x*Math.sin(rad)-accel.z*Math.cos(rad));
            float sideways=(float)(accel.x*Math.cos(rad)+accel.z*Math.sin(rad));
            float turn=fresh?0:Mth.wrapDegrees(yaw-s.yaw)*Mth.DEG_TO_RAD;
            if(mob.kind()==TemplateMob.Kind.PRIEST)for(int j=0;j<14;j++){
                int side=j<8?j/4:j%2;
                float armDelta=fresh?0:(side==0?armR-s.rightArm:armL-s.leftArm);
                boolean distal=j<8?j%2==1:j>=11;
                float limit=(j<8?(distal?18:10):25)*Mth.DEG_TO_RAD;
                float target=Mth.clamp(-forward*2.4F-armDelta*.35F, -limit,limit);
                float targetRoll=Mth.clamp(-sideways*2-turn*.55F,-limit,limit);
                // Distal sections react to the parent's prior displacement and retain momentum.
                if(distal){int parent=j<8?j-1:j-3;target=Mth.clamp(target+s.angle[parent]*.35F,-limit,limit);targetRoll=Mth.clamp(targetRoll+s.roll[parent]*.35F,-limit,limit);}
                for(int n=0;n<steps;n++){
                    float k=distal?55:80,d=distal?11:14;
                    s.speed[j]+=(k*(target-s.angle[j])-d*s.speed[j])*.05F;
                    s.rollSpeed[j]+=(k*(targetRoll-s.roll[j])-d*s.rollSpeed[j])*.05F;
                    s.angle[j]=Mth.clamp(s.angle[j]+s.speed[j]*.05F,-limit,limit);
                    s.roll[j]=Mth.clamp(s.roll[j]+s.rollSpeed[j]*.05F,-limit,limit);
                }
            }
            if(mob.kind()==TemplateMob.Kind.SHIELD)for(int i=0;i<2;i++){
                float arm=i==0?armR:armL;
                float pulse=v.horizontalDistanceSqr()>.0001?Math.max(0,Mth.sin((mob.tickCount+i*10)*.32F))*.35F:0;
                float target=Mth.clamp(Math.abs(Mth.sin(arm))*.85F+pulse,0,1.2F);
                for(int n=0;n<steps;n++)s.rail[i]+=(target-s.rail[i])*.62F;
            }
            String[] gear=gearBones(mob.kind());
            for(int j=0;j<gear.length;j++){
                float limit=(mob.kind()==TemplateMob.Kind.FLAG?8:mob.kind()==TemplateMob.Kind.SCOUT?12:7)*Mth.DEG_TO_RAD;
                // Acceleration/yaw/body-action response only. Authored idle waves remain on
                // child bones; these identity wrappers never accumulate their transforms.
                float bodyDelta=fresh?0:armR-s.rightArm;
                float target=Mth.clamp(-forward*1.8F-bodyDelta*.14F,-limit,limit);
                float targetRoll=Mth.clamp(-sideways*1.5F-turn*.38F,-limit,limit);
                if(mob.kind()==TemplateMob.Kind.FLAG&&j>0){target+=s.angle[j-1]*.25F;targetRoll+=s.roll[j-1]*.25F;}
                target=Mth.clamp(target,-limit,limit);targetRoll=Mth.clamp(targetRoll,-limit,limit);
                for(int n=0;n<steps;n++){
                    s.speed[j]+=(58*(target-s.angle[j])-12*s.speed[j])*.05F;
                    s.rollSpeed[j]+=(58*(targetRoll-s.roll[j])-12*s.rollSpeed[j])*.05F;
                    s.angle[j]=Mth.clamp(s.angle[j]+s.speed[j]*.05F,-limit,limit);
                    s.roll[j]=Mth.clamp(s.roll[j]+s.rollSpeed[j]*.05F,-limit,limit);
                }
            }
            s.velocity=v;s.yaw=yaw;s.rightArm=armR;s.leftArm=armL;s.tick=now;
        }
        if(mob.kind()==TemplateMob.Kind.PRIEST){
            int j=0;for(String side:SIDES)for(String part:new String[]{"sleeve_inner_spring","sleeve_inner_tip","sleeve_outer_spring","sleeve_outer_tip"})set(model,side+"_"+part,s.angle[j],s.roll[j++]);
            float cast=mob.skillId()==0?1:.35F;
            for(int i=0;i<3;i++){set(model,"talisman_spring_"+i,s.angle[8+i]*cast,s.roll[8+i]*cast);set(model,"talisman_tip_"+i,s.angle[11+i]*cast,s.roll[11+i]*cast);}
        }else if(mob.kind()==TemplateMob.Kind.SHIELD){
            for(int i=0;i<2;i++){final float y=s.rail[i];model.getBone(SIDES[i]+"_shoulder_rail").ifPresent(b->b.setPosY(y));set(model,SIDES[i]+"_hip_plate_lower",Mth.clamp(rotation(model,SIDES[i]+"_knee")*.2F,-.14F,.14F),0);}
        }else if(mob.kind()==TemplateMob.Kind.BEAST&&mob.onClimbable()&&mob.climbFace()!=null&&mob.skillId()==0){
            if(advance)solveClimb(model,mob,s,now);
            for(int i=0;i<2;i++)for(int j=0;j<6;j++){
                int index=i*6+j;
                set(model,SIDES[i]+"_climb_"+IK_PARTS[j],s.ik[index],s.ikZ[index]);
                model.getBone(SIDES[i]+"_climb_"+IK_PARTS[j]).ifPresent(b->b.setRotY(s.ikY[index]));
            }
        }else if(mob.kind()==TemplateMob.Kind.BEAST){s.face=null;java.util.Arrays.fill(s.stance,false);java.util.Arrays.fill(s.ik,0);}
        if(mob.kind()==TemplateMob.Kind.SCORPION&&!mob.burrowed()&&mob.skillId()!=com.dynasty.blueprint.ArmySkills.SCORPION_EMERGE){
            if(advance)solveScorpion(mob,s,now);
            for(int i=0;i<6;i++){set(model,"leg_ik_hip_"+i,0,s.scorpionLeg[i*2]);set(model,"leg_ik_knee_"+i,0,s.scorpionLeg[i*2+1]);}
        }
        String[] gear=gearBones(mob.kind());
        for(int j=0;j<gear.length;j++)set(model,gear[j],s.angle[j],s.roll[j]);
        if(mob.kind()==TemplateMob.Kind.CHILD)model.getBone("lamp_inertia").ifPresent(b->b.setRotY(s.roll[0]*.7F));
    }
    private static String[] gearBones(TemplateMob.Kind kind){return switch(kind){
        case SPEAR->SPEAR_GEAR;case CROSSBOW->CROSSBOW_GEAR;case SCOUT->SCOUT_GEAR;case FLAG->FLAG_GEAR;case CHILD->CHILD_GEAR;case SKULL->SKULL_GEAR;case TREE->TREE_GEAR;default->NO_GEAR;};}
    private static final String[] TREE_GEAR={"root_spring_0","root_spring_1","root_spring_2","root_spring_3","root_spring_4","root_spring_5"},SKULL_GEAR={"viscera_spring_0","viscera_spring_1","viscera_spring_2","viscera_spring_3"},CHILD_GEAR={"lamp_inertia","ribbon_spring_0","ribbon_spring_1","ribbon_spring_2"},NO_GEAR={},SPEAR_GEAR={"skirt_spring_front","skirt_spring_back","skirt_spring_left","skirt_spring_right"},
        CROSSBOW_GEAR={"gear_pouch_0","gear_pouch_1","gear_pouch_2"},SCOUT_GEAR={"right_chain_spring","left_chain_spring"},
        FLAG_GEAR={"flag_spring_0","flag_spring_1","flag_spring_2","flag_spring_3"};
    private static void resetProcedural(TemplateMobModel model,TemplateMob.Kind kind){
        if(kind==TemplateMob.Kind.PRIEST){for(String side:SIDES)for(String n:new String[]{"sleeve_inner_spring","sleeve_inner_tip","sleeve_outer_spring","sleeve_outer_tip"})reset(model,side+"_"+n);for(int i=0;i<3;i++){reset(model,"talisman_spring_"+i);reset(model,"talisman_tip_"+i);}}
        if(kind==TemplateMob.Kind.SHIELD)for(String side:SIDES){reset(model,side+"_shoulder_rail");reset(model,side+"_hip_plate_lower");}
        if(kind==TemplateMob.Kind.BEAST)for(String side:SIDES)for(String part:IK_PARTS)reset(model,side+"_climb_"+part);
        if(kind==TemplateMob.Kind.SCORPION)for(int i=0;i<6;i++){reset(model,"leg_ik_hip_"+i);reset(model,"leg_ik_knee_"+i);}
        for(String gear:gearBones(kind))reset(model,gear);
    }
    private static void reset(TemplateMobModel model,String name){model.getBone(name).ifPresent(b->{b.setRotX(0);b.setRotY(0);b.setRotZ(0);b.setPosX(0);b.setPosY(0);b.setPosZ(0);});}
    private static void set(TemplateMobModel model,String name,float x,float z){model.getBone(name).ifPresent(b->{b.setRotX(x);b.setRotZ(z);});}
    private static float rotation(TemplateMobModel model,String name){return model.getBone(name).map(GeoBone::getRotX).orElse(0F);}

