@Mod.EventBusSubscriber(modid = "dynasty", bus = Mod.EventBusSubscriber.Bus.MOD, value = Dist.CLIENT)
public final class TemplateMobRenderer extends GeoEntityRenderer<TemplateMob> {
    public TemplateMobRenderer(EntityRendererProvider.Context context) {
        super(context, new TemplateMobModel());
        shadowRadius = 0.5F;
    }

    @SubscribeEvent public static void register(EntityRenderersEvent.RegisterRenderers event) {
        event.registerEntityRenderer(BlueprintEntities.BISHUI_XUANJIAO_YOUZI.get(),TemplateMobRenderer::new);
        event.registerEntityRenderer(BlueprintEntities.JUBI_SHIGANDANG.get(),TemplateMobRenderer::new);
        event.registerEntityRenderer(BlueprintEntities.XUNSHAN_MUJIAQUAN.get(),TemplateMobRenderer::new);
        event.registerEntityRenderer(BlueprintEntities.QINGTONG_SHUANGTOUSHEKUI.get(),TemplateMobRenderer::new);
        event.registerEntityRenderer(BlueprintEntities.YINYANG_ZHIJIAO_YOUHUN.get(),TemplateMobRenderer::new);
        event.registerEntityRenderer(BlueprintEntities.TONGBI_FEITIAN_YECHA.get(),TemplateMobRenderer::new);
        event.registerEntityRenderer(BlueprintEntities.BAIMU_MOWU.get(),TemplateMobRenderer::new);
        event.registerEntityRenderer(BlueprintEntities.JULI_BIXI_KUILEI.get(),TemplateMobRenderer::new);
        event.registerEntityRenderer(BlueprintEntities.SHASHUI_FUNIGUI.get(),TemplateMobRenderer::new);
        event.registerEntityRenderer(BlueprintEntities.XUEJU_MANGGUYU.get(),TemplateMobRenderer::new);
        event.registerEntityRenderer(BlueprintEntities.YOUDENG_GUIMIANFU.get(),TemplateMobRenderer::new);
        event.registerEntityRenderer(BlueprintEntities.BAZU_DIGONGZHU.get(),TemplateMobRenderer::new);
        event.registerEntityRenderer(BlueprintEntities.ZUWU_DAOSHOU.get(), TemplateMobRenderer::new);
        event.registerEntityRenderer(BlueprintEntities.LUDUN_JIASHI.get(), TemplateMobRenderer::new);
        event.registerEntityRenderer(BlueprintEntities.FUFA_JIJIU.get(), TemplateMobRenderer::new);
        event.registerEntityRenderer(BlueprintEntities.SHANJING_SHANXIAO.get(), TemplateMobRenderer::new);
        event.registerEntityRenderer(BlueprintEntities.JUMA_CHANGQIANGBING.get(), TemplateMobRenderer::new);
        event.registerEntityRenderer(BlueprintEntities.LIANNU_ZHENZU.get(), TemplateMobRenderer::new);
        event.registerEntityRenderer(BlueprintEntities.TIESUO_CHIHOU.get(), TemplateMobRenderer::new);
        event.registerEntityRenderer(BlueprintEntities.KUIJUN_SISHI.get(), TemplateMobRenderer::new);
        event.registerEntityRenderer(BlueprintEntities.ZHENWANG_ZHANGQIGUAN.get(), TemplateMobRenderer::new);
        event.registerEntityRenderer(BlueprintEntities.PIJIA_PANJIANG_HUWEI.get(), TemplateMobRenderer::new);
        event.registerEntityRenderer(BlueprintEntities.YINBING_GUIZU.get(), TemplateMobRenderer::new);
        event.registerEntityRenderer(BlueprintEntities.SHIBIAN_LISHI.get(), TemplateMobRenderer::new);
        event.registerEntityRenderer(BlueprintEntities.FUHUN_BAIBU_TONGZI.get(), TemplateMobRenderer::new);
        event.registerEntityRenderer(BlueprintEntities.ZHIREN_JIANKE.get(), TemplateMobRenderer::new);
        event.registerEntityRenderer(BlueprintEntities.KUMU_SHUJING.get(),TemplateMobRenderer::new);
        event.registerEntityRenderer(BlueprintEntities.MINGSHA_SHIXIE.get(),TemplateMobRenderer::new);
        event.registerEntityRenderer(BlueprintEntities.ROOT_SNARE.get(),RootSnareRenderer::new);
        event.registerEntityRenderer(BlueprintEntities.CHIMU_ZHUHA.get(),TemplateMobRenderer::new);
        event.registerEntityRenderer(BlueprintEntities.TOAD_VENOM_POOL.get(),net.minecraft.client.renderer.entity.NoopRenderer::new);
        event.registerEntityRenderer(BlueprintEntities.MUXUE_FEILU.get(), TemplateMobRenderer::new);
        event.registerEntityRenderer(BlueprintEntities.SKULL_BLOOD_POOL.get(), net.minecraft.client.renderer.entity.NoopRenderer::new);
