        event.registerEntityRenderer(BlueprintEntities.ARMY_CALTROP.get(), ThrownItemRenderer::new);
        event.registerEntityRenderer(BlueprintEntities.TEMPLATE_PROJECTILE.get(), ThrownItemRenderer::new);
    }

    @Override public void render(TemplateMob mob, float yaw, float partialTick, PoseStack pose,
                                 MultiBufferSource buffers, int light) {
        pose.pushPose();
        try {
            if (mob.isPossessed()) pose.scale(1.15F, 1.15F, 1.15F);
            super.render(mob, yaw, partialTick, pose, buffers, light);
        } finally {
            pose.popPose();
        }
    }

    @Override protected float getDeathMaxRotation(TemplateMob mob) {
        // Authored kneeling/collapse clips own death rotation; vanilla's 90-degree roll would
        // tip the shield cover onto its side for its remaining server-authoritative lifetime.
        return 0;
    }

    @Override protected void applyRotations(TemplateMob mob, PoseStack pose, float age, float bodyYaw, float partialTick) {
        if((mob.kind()==TemplateMob.Kind.MINING_SPIDER||mob.kind()==TemplateMob.Kind.CENTIPEDE)&&mob.hanging()&&mob.isAlive()){
            super.applyRotations(mob,pose,age,bodyYaw,partialTick);
            pose.translate(0,mob.getBbHeight(),0);pose.mulPose(Axis.ZP.rotationDegrees(180));return;
        }
        var wall = mob.climbFace();
        if (mob.kind() != TemplateMob.Kind.BEAST || !mob.isAlive() || mob.skillId() != 0
                || !mob.onClimbable() || wall == null) {
            super.applyRotations(mob, pose, age, bodyYaw, partialTick);
            return;
        }
        // Bind the authored ground plane to the measured wall, not to the target's yaw.
        // Model +Y points away from stone; model -Z climbs upward. The .88 rise keeps
        // the short tail above the floor at first contact. This is strictly visual:
        // the server's physical position, navigation and attack origin are untouched.
        double distance = Math.max(0, mob.climbContactDistance() - .02);
        pose.translate(wall.getStepX() * distance, .88, wall.getStepZ() * distance);
        pose.mulPose(Axis.YP.rotationDegrees(180F - wall.toYRot()));
        pose.mulPose(Axis.XP.rotationDegrees(90F));
    }

    @Override public void renderRecursively(PoseStack pose,TemplateMob mob,software.bernie.geckolib.cache.object.GeoBone bone,
            net.minecraft.client.renderer.RenderType type,MultiBufferSource buffers,com.mojang.blaze3d.vertex.VertexConsumer sink,
            boolean rerender,float partial,int light,int overlay,float red,float green,float blue,float alpha) {
        boolean vein=mob.kind()==TemplateMob.Kind.CORPSE&&bone.getName().startsWith("vein_");
        super.renderRecursively(pose,mob,bone,type,buffers,sink,rerender,partial,vein||mob.kind()==TemplateMob.Kind.CENTIPEDE&&bone.getName().startsWith("eye_")&&mob.skillId()==com.dynasty.blueprint.ArmySkills.CENTIPEDE_GAZE||mob.kind()==TemplateMob.Kind.BLIND_FISH&&(bone.getName().startsWith("dorsal_")||bone.getName().startsWith("ribbon_"))||mob.kind()==TemplateMob.Kind.LANTERN_BAT&&bone.getName().equals("flame")||mob.kind()==TemplateMob.Kind.TREE&&bone.getName().startsWith("fungus_")||mob.kind()==TemplateMob.Kind.TOAD&&(bone.getName().startsWith("venom_gland_")||bone.getName().startsWith("eye_"))||mob.kind()==TemplateMob.Kind.CHILD&&bone.getName().equals("lantern_flame")?15728880:light,overlay,
            vein?.75F:red,vein?.25F:green,vein?1F:blue,alpha);
    }

    @Override public Color getRenderColor(TemplateMob mob, float partialTick, int light) {
        if(mob.kind()==TemplateMob.Kind.DROWNER)return Color.ofRGBA(.32F,.46F,.49F,.65F);
        if(mob.kind()==TemplateMob.Kind.BLIND_FISH)return Color.ofRGBA(1F,1F,.95F,mob.isDeadOrDying()?Math.max(0,.72F*(1-mob.actionAge(partialTick)/44F)):.72F);
        if (mob.kind() == TemplateMob.Kind.GHOST) return Color.ofRGBA(.55F,.85F,1F,mob.isPhased()?.18F:.65F);
        if (mob.kind() == TemplateMob.Kind.BEAST && mob.isDeadOrDying()) {
            // The native blue-green fur loses its cool hue toward dry charcoal as it curls.
            // Use the synchronized death clock, so late observers do not restart the fade.
            // Vertex tint needs neither a second texture nor an extra render pass/entity.
            float fade = Mth.clamp((mob.actionAge(partialTick) - 6F) / 26F, 0F, 1F);
            return Color.ofRGB(1F - .10F * fade, 1F - .26F * fade, 1F - .46F * fade);
        }
        if(mob.getPersistentData().getBoolean("DynastyEventPhantom"))return Color.ofRGBA(.35F,.85F,1F,.35F);
        return super.getRenderColor(mob, partialTick, light);
    }

    @Override public net.minecraft.client.renderer.RenderType getRenderType(TemplateMob mob,
            net.minecraft.resources.ResourceLocation texture,MultiBufferSource buffers,float partialTick){
        return (mob.kind()==TemplateMob.Kind.GHOST||mob.kind()==TemplateMob.Kind.BLIND_FISH||mob.kind()==TemplateMob.Kind.DROWNER)?net.minecraft.client.renderer.RenderType.entityTranslucent(texture)
            :super.getRenderType(mob,texture,buffers,partialTick);
    }

    @Override public int getPackedOverlay(TemplateMob mob, float u, float partialTick) {
        // The shield remnant is usable cover for ten seconds, not a ten-second hurt flash.
        // Keep the initial vanilla impact flash, then restore its authored metal/wood colours.
        if (mob.isDeadOrDying() && (mob.hurtTime <= 0 || mob.kind()==TemplateMob.Kind.PAPER)) return OverlayTexture.NO_OVERLAY;
        return super.getPackedOverlay(mob, u, partialTick);
    }
}

package com.dynasty.blueprint;

/** Shared locomotion semantics; every species retains its own authored rig, clips and attack clock. */
public enum AnimationProfile {
    LIGHT_HUMANOID(false,32),HEAVY_HUMANOID(false,24),ARCHER(false,32),BLADE(false,32),SPEAR(false,32),CASTER(false,32),
    QUADRUPED(false,32),MULTILEG(false,24),SERPENT(false,32),FLOATING(true,24),GIANT_CONSTRUCT(false,24);
    private final boolean floating;private final int secondaryDistance;
    AnimationProfile(boolean floating,int secondaryDistance){this.floating=floating;this.secondaryDistance=secondaryDistance;}
    public boolean floating(){return floating;}
    public int secondaryDistance(){return secondaryDistance;}
    public boolean loops(String clip){return switch(clip){case "idle","walk","run","fly","climb","burrow","camouflage"->true;default->false;};}
    /** Rate changes affect only locomotion. Attack/death clips continue to seek the authoritative server epoch. */
    public double playbackRate(String clip,double horizontalSpeed,double movementAttribute,boolean sprinting){
        if(!clip.equals("walk")&&!clip.equals("run")&&!clip.equals("fly"))return 1;
        if(floating)return 1;
        double nominal=Math.max(.035,movementAttribute*(sprinting?.6:.35));
        return net.minecraft.util.Mth.clamp(horizontalSpeed/nominal,.65,1.5);
    }
    public static AnimationProfile forKind(TemplateMob.Kind kind){
        return switch(kind){
            case SWORD->BLADE;case SPEAR->SPEAR;case CROSSBOW->ARCHER;case SHIELD,AXE_GUARD,CORPSE->HEAVY_HUMANOID;
            case PRIEST,FLAG->CASTER;case SCOUT,POWDER,PAPER->LIGHT_HUMANOID;case BEAST,TOAD->QUADRUPED;
            case SCORPION,MINING_SPIDER,CENTIPEDE->MULTILEG;case SERPENT,BRONZE_SNAKE->SERPENT;
            case GHOST,CHILD,SKULL,LANTERN_BAT,BLIND_FISH,YECHA,PALANQUIN->FLOATING;
            case STONE_GUARD,TREE,BIXI->GIANT_CONSTRUCT;case CLOCKWORK_DOG->QUADRUPED;case DROWNER->LIGHT_HUMANOID;
        };
    }
}

